 37	export function parseCommandLine(argv, programName) {
 38	  let parsedAmount;
 39	  let currency;
 40	  let helpRequested = false;
 41	  const extras = [];
 42	
 43	  for (let index = 0; index < argv.length; index += 1) {
 44	    const token = argv[index];
 45	
 46	    if (token === '--') {
 47	      extras.push(...argv.slice(index));
 48	      break;
 49	    }
 50	
 51	    const shortHelpArgument = getShortHelpArgument(token);
 52	    if (shortHelpArgument !== null) {
 53	      throw createArgumentError(
 54	        programName,
 55	        `argument -h/--help: ignored explicit argument '${shortHelpArgument}'`,
 56	      );
 57	    }
 58	
 59	    if (isShortHelpToken(token)) {
 60	      helpRequested = true;
 61	      continue;
 62	    }
 63	
 64	    const matchedOption = matchLongOption(token);
 65	    if (matchedOption === null) {
 66	      extras.push(token);
 67	      continue;
 68	    }
 69	
 70	    if (matchedOption.option === HELP_OPTION) {
 71	      if (matchedOption.inlineValue !== null) {
 72	        throw createArgumentError(
 73	          programName,
 74	          `argument -h/--help: ignored explicit argument '${matchedOption.inlineValue}'`,
 75	        );
 76	      }
 77	      helpRequested = true;
 78	      continue;
 79	    }
 80	
 81	    const rawValue =
 82	      matchedOption.inlineValue !== null
 83	        ? matchedOption.inlineValue
 84	        : consumeNextValue(argv, index, matchedOption.option, programName);
 85	
 86	    if (matchedOption.inlineValue === null) {
 87	      index += 1;
 88	    }
 89	
 90	    if (matchedOption.option === AMOUNT_OPTION) {
 91	      parsedAmount = parseAmountValue(rawValue, programName);
 92	    } else if (matchedOption.option === CURRENCY_OPTION) {
 93	      currency = rawValue;
 94	    }
 95	  }
 96	
 97	  if (helpRequested) {
 98	    throw new CliExit(0, { stdout: buildHelpText(programName) });
 99	  }
100	
101	  const missingArguments = [];
102	  if (parsedAmount === undefined) {
103	    missingArguments.push('--amount');
104	  }
105	  if (currency === undefined) {
106	    missingArguments.push('--currency');
107	  }
108	
109	  if (missingArguments.length > 0) {
110	    throw createArgumentError(
111	      programName,
112	      `the following arguments are required: ${missingArguments.join(', ')}`,
113	    );
114	  }
115	
116	  if (extras.length > 0) {
117	    throw createArgumentError(
118	      programName,
119	      `unrecognized arguments: ${extras.join(' ')}`,
120	    );
121	  }
122	
123	  return {
124	    amount: parsedAmount,
125	    currency,
126	  };
127	}
