143	function consumeNextValue(argv, currentIndex, option, programName) {
144	  const nextValue = argv[currentIndex + 1];
145	  if (nextValue === undefined) {
146	    throw createArgumentError(
147	      programName,
148	      `argument ${option.longName}: expected one argument`,
149	    );
150	  }
151	
152	  if (nextValue.startsWith('-')) {
153	    if (option === AMOUNT_OPTION && NEGATIVE_NUMBER_TOKEN.test(nextValue)) {
154	      return nextValue;
155	    }
156	
157	    throw createArgumentError(
158	      programName,
159	      `argument ${option.longName}: expected one argument`,
160	    );
161	  }
162	
163	  return nextValue;
164	}
