166	function matchLongOption(token) {
167	  if (!token.startsWith('--') || token === '--') {
168	    return null;
169	  }
170	
171	  const equalsIndex = token.indexOf('=');
172	  const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
173	  const inlineValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
174	
175	  const matchingOptions = LONG_OPTIONS.filter(({ longName }) =>
176	    longName.startsWith(optionName),
177	  );
178	
179	  if (matchingOptions.length !== 1) {
180	    return null;
181	  }
182	
183	  return {
184	    option: matchingOptions[0],
185	    inlineValue,
186	  };
187	}
