  7	export class InvalidFloatValueError extends Error {
  8	  constructor(rawValue) {
  9	    super(`invalid float value: '${rawValue}'`);
 10	    this.name = 'InvalidFloatValueError';
 11	    this.rawValue = rawValue;
 12	  }
