 15	export function parsePythonFloatToken(rawValue) {
 16	  if (!isPythonFloatToken(rawValue)) {
 17	    throw new InvalidFloatValueError(rawValue);
 18	  }
 19	
 20	  const normalized = rawValue.replaceAll('_', '');
 21	  const lower = normalized.toLowerCase();
 22	
 23	  if (lower === 'nan' || lower === '+nan' || lower === '-nan') {
 24	    return { kind: 'nan', negative: false, rawValue };
 25	  }
 26	
 27	  if (
 28	    lower === 'inf' ||
 29	    lower === '+inf' ||
 30	    lower === 'infinity' ||
 31	    lower === '+infinity'
 32	  ) {
 33	    return { kind: 'infinity', negative: false, rawValue };
 34	  }
 35	
 36	  if (lower === '-inf' || lower === '-infinity') {
 37	    return { kind: 'infinity', negative: true, rawValue };
 38	  }
 39	
 40	  const numericValue = Number(normalized);
 41	  if (Number.isNaN(numericValue)) {
 42	    throw new InvalidFloatValueError(rawValue);
 43	  }
 44	
 45	  if (!Number.isFinite(numericValue)) {
 46	    return {
 47	      kind: 'infinity',
 48	      negative: normalized.startsWith('-'),
 49	      rawValue,
 50	    };
 51	  }
 52	
 53	  const negative = numericValue < 0 || Object.is(numericValue, -0);
 54	  const { integerPart, fractionalPart } = buildFiniteParts(normalized, numericValue);
 55	
 56	  return {
 57	    kind: 'finite',
 58	    negative,
 59	    integerPart,
 60	    fractionalPart,
 61	    rawValue,
 62	  };
 63	}
