 65	export function formatParsedAmount(parsedAmount, decimalPlaces) {
 66	  if (parsedAmount.kind === 'nan') {
 67	    if (decimalPlaces === 0) {
 68	      return 'NaN';
 69	    }
 70	    return `NaN.${'0'.repeat(decimalPlaces)}`;
 71	  }
 72	
 73	  if (parsedAmount.kind === 'infinity') {
 74	    return 'INF';
 75	  }
 76	
 77	  const rounded = roundHalfEven(
 78	    parsedAmount.integerPart,
 79	    parsedAmount.fractionalPart,
 80	    decimalPlaces,
 81	  );
 82	
 83	  if (decimalPlaces === 0) {
 84	    return rounded.integerPart;
 85	  }
 86	
 87	  return `${rounded.integerPart}.${rounded.fractionalPart}`;
 88	}
