102	function buildFiniteParts(normalizedLiteral, numericValue) {
103	  if (numericValue === 0 || Object.is(numericValue, -0)) {
104	    return { integerPart: '0', fractionalPart: '' };
105	  }
106	
107	  const signless = normalizedLiteral.replace(/^[+-]/, '');
108	  const match = signless.match(
109	    /^((\d+)(?:\.(\d*))?|\.(\d+))(?:[eE]([+-]?\d+))?$/,
110	  );
111	
112	  const integerDigits = match[2] ?? '';
113	  const fractionalDigits = match[3] ?? match[4] ?? '';
114	  const exponent = Number(match[5] ?? '0');
115	  const digits = `${integerDigits}${fractionalDigits}`;
116	  const decimalIndex = integerDigits.length + exponent;
117	
118	  if (decimalIndex <= 0) {
119	    return {
120	      integerPart: '0',
121	      fractionalPart: `${'0'.repeat(-decimalIndex)}${digits}`,
122	    };
123	  }
124	
125	  if (decimalIndex >= digits.length) {
126	    return {
127	      integerPart: stripLeadingZeros(`${digits}${'0'.repeat(decimalIndex - digits.length)}`),
128	      fractionalPart: '',
129	    };
130	  }
131	
132	  return {
133	    integerPart: stripLeadingZeros(digits.slice(0, decimalIndex)),
134	    fractionalPart: digits.slice(decimalIndex),
135	  };
136	}
