138	function roundHalfEven(integerPart, fractionalPart, decimalPlaces) {
139	  const keptFraction = fractionalPart.slice(0, decimalPlaces).padEnd(decimalPlaces, '0');
140	  const nextDigit = fractionalPart[decimalPlaces] ?? '0';
141	  const trailingDigits = fractionalPart.slice(decimalPlaces + 1);
142	
143	  let shouldRoundUp = false;
144	  if (nextDigit > '5') {
145	    shouldRoundUp = true;
146	  } else if (nextDigit === '5') {
147	    if (/[1-9]/.test(trailingDigits)) {
148	      shouldRoundUp = true;
149	    } else {
150	      const lastKeptDigit =
151	        decimalPlaces === 0
152	          ? integerPart[integerPart.length - 1] ?? '0'
153	          : keptFraction[keptFraction.length - 1];
154	      shouldRoundUp = Number(lastKeptDigit) % 2 === 1;
155	    }
156	  }
157	
158	  if (!shouldRoundUp) {
159	    return { integerPart, fractionalPart: keptFraction };
160	  }
161	
162	  const incremented = incrementDigitString(`${integerPart}${keptFraction}`);
163	  if (decimalPlaces === 0) {
164	    return { integerPart: incremented, fractionalPart: '' };
165	  }
166	
167	  const splitIndex = incremented.length - decimalPlaces;
168	  return {
169	    integerPart: incremented.slice(0, splitIndex),
170	    fractionalPart: incremented.slice(splitIndex),
171	  };
172	}
173	
174	function incrementDigitString(digits) {
175	  const result = digits.split('');
176	  let carry = 1;
177	
178	  for (let index = result.length - 1; index >= 0 && carry === 1; index -= 1) {
179	    const nextDigit = result[index].charCodeAt(0) - 48 + carry;
180	    if (nextDigit === 10) {
181	      result[index] = '0';
182	    } else {
183	      result[index] = String(nextDigit);
184	      carry = 0;
185	    }
186	  }
187	
188	  if (carry === 1) {
189	    result.unshift('1');
190	  }
191	
192	  return stripLeadingZeros(result.join(''));
193	}
